export function mergeRecords(records, incoming) {
  for (const record of incoming) {
    const index = records.findIndex(old => String(old.id) === String(record.id));
    if (index < 0) records.push(record);
    else records[index] = { ...records[index], ...record };
  }
  return records;
}

